   ========================================================================== */

function PeopleMix({
  stats,
}: {
  role?: string
  stats: {
    label: string
    value: number
    icon: any
  }[]
}) {
  const total = stats.reduce(
    (sum, item) => sum + Number(item.value || 0),
    0,
  )

  return (
    <section className="overflow-hidden rounded-2xl border border-gray-200 bg-white">
      <div className="border-b border-gray-100 px-6 py-5">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-sm font-semibold text-gray-950">
              People overview
            </h2>

            <p className="mt-1 text-xs text-gray-400">
              Current people distribution
            </p>
          </div>

          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gray-50">
            <Users size={15} className="text-gray-600" />
          </div>
        </div>
      </div>

      <div className="p-6">
        {stats.length ? (
          <div className="space-y-5">
            {stats.map((item) => {
              const percentage =
                total > 0
                  ? Math.round(
                      (Number(item.value || 0) / total) * 100,
                    )
                  : 0

              return (
                <div key={item.label}>
                  <div className="mb-2 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gray-50">
                        <item.icon
                          size={13}
                          className="text-gray-600"
                        />
                      </div>

                      <span className="text-xs font-medium text-gray-700">
                        {item.label}
                      </span>
                    </div>

                    <div className="flex items-center gap-2">
                      <span className="text-xs font-semibold text-gray-900">
                        {item.value}
                      </span>

                      <span className="text-[10px] text-gray-400">
                        {percentage}%
                      </span>
                    </div>
                  </div>

                  <div className="h-1.5 overflow-hidden rounded-full bg-gray-100">
                    <div
                      className="h-full rounded-full bg-gray-950 transition-all duration-700"
                      style={{
                        width: `${percentage}%`,
                      }}
                    />
                  </div>
                </div>
              )
            })}
          </div>
        ) : (
          <div className="py-8 text-center text-xs text-gray-400">
            No people data available.
          </div>
        )}
      </div>
    </section>
  )
}

