                  <span className="rounded-full bg-gray-100 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-gray-500">
                    {roleLabel}
                  </span>
                </div>

                <h1 className="text-2xl font-semibold tracking-tight text-gray-950 sm:text-3xl">
                  Good afternoon, {firstName}
                </h1>

                <p className="mt-1 max-w-2xl text-sm text-gray-500">
                  {subtitle[role ?? 'employee']}
                </p>
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-2">
              {role === 'admin' && (
                <Link
                  to="/dashboard/users"
                  className="inline-flex h-10 items-center gap-2 rounded-xl bg-gray-950 px-4 text-xs font-semibold text-white shadow-sm transition hover:bg-gray-800"
                >
                  <Plus size={15} />
                  Add user
                </Link>
              )}

              {isSuperAdmin && (
                <Link
                  to="/dashboard/organizations"
                  className="inline-flex h-10 items-center gap-2 rounded-xl bg-gray-950 px-4 text-xs font-semibold text-white shadow-sm transition hover:bg-gray-800"
                >
                  <Plus size={15} />
                  New organization
                </Link>
              )}

              <Link
                to="/dashboard/announcements"
                className="inline-flex h-10 items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 text-xs font-semibold text-gray-700 transition hover:border-gray-300 hover:bg-gray-50"
              >
                <Bell size={15} />
                Notifications
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* ------------------------------------------------------------------ */}
      {/* STATS                                                              */}
      {/* ------------------------------------------------------------------ */}

      {isLoadingStats ? (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
          {Array.from({
            length: Math.max(stats.length, 3),
          }).map((_, index) => (
            <div
              key={index}
              className="h-36 animate-pulse rounded-2xl border border-gray-200 bg-white"
            />
          ))}
        </div>
      ) : (
        <div
          className={`grid grid-cols-1 gap-4 ${
            stats.length >= 4
              ? 'sm:grid-cols-2 xl:grid-cols-4'
              : 'sm:grid-cols-2 lg:grid-cols-3'
          }`}
        >
          {stats.map((stat) => (
            <DashboardStatCard
              key={stat.label}
              item={stat}
            />
          ))}
        </div>
      )}

      {/* ------------------------------------------------------------------ */}
      {/* QUICK ACTIONS                                                      */}
      {/* ------------------------------------------------------------------ */}

      <QuickActions actions={quickActions} />

      {/* ------------------------------------------------------------------ */}
      {/* MAIN GRID                                                          */}
      {/* ------------------------------------------------------------------ */}

      <div className="grid grid-cols-1 gap-6 xl:grid-cols-12">
        {/* -------------------------------------------------------------- */}
        {/* ORGANIZATIONS                                                   */}
        {/* -------------------------------------------------------------- */}

        {canViewOrganizations && (
          <div className="xl:col-span-7">
            <OrganizationsPanel
              organizations={
                orgsQ.data?.data ?? []
              }
              isLoading={orgsQ.isLoading}
              isSuperAdmin={isSuperAdmin}
            />
          </div>
        )}

        {/* -------------------------------------------------------------- */}
        {/* PEOPLE                                                          */}
        {/* -------------------------------------------------------------- */}

        {peopleStats.length > 0 && (
          <div
            className={
              canViewOrganizations
                ? 'xl:col-span-5'
                : 'xl:col-span-6'
            }
          >
            <PeopleMix
              role={role}
              stats={peopleStats}
            />
          </div>
        )}

        {/* -------------------------------------------------------------- */}
        {/* ANNOUNCEMENTS                                                   */}
        {/* -------------------------------------------------------------- */}

        <div
          className={
            canViewOrganizations
              ? 'xl:col-span-7'
              : 'xl:col-span-6'
          }
        >
          <AnnouncementsWidget />
        </div>

        {/* -------------------------------------------------------------- */}
        {/* WORKSPACE HEALTH                                                */}
        {/* -------------------------------------------------------------- */}

        <section
          className={
            canViewOrganizations
              ? 'xl:col-span-5'
              : 'xl:col-span-6'
          }
        >
          <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white">
            <div className="border-b border-gray-100 px-6 py-5">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-sm font-semibold text-gray-950">
                    Workspace
                  </h2>

                  <p className="mt-1 text-xs text-gray-400">
                    Quick overview of your workspace
                  </p>
                </div>

                <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-emerald-50">
                  <ShieldCheck
                    size={15}
                    className="text-emerald-600"
                  />
                </div>
              </div>
            </div>

            <div className="p-6">
              <div className="space-y-3">
                <div className="flex items-center justify-between rounded-xl bg-gray-50 px-4 py-3">
                  <div className="flex items-center gap-3">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-white shadow-sm">
                      <CheckCircle2
                        size={15}
                        className="text-emerald-600"
                      />
                    </div>

                    <div>
                      <p className="text-xs font-semibold text-gray-800">
                        Account status
                      </p>

                      <p className="text-[11px] text-gray-400">
                        Your account is active
                      </p>
                    </div>
                  </div>

                  <span className="text-[10px] font-semibold uppercase tracking-wider text-emerald-600">
                    Active
                  </span>
                </div>

                <div className="flex items-center justify-between rounded-xl bg-gray-50 px-4 py-3">
                  <div className="flex items-center gap-3">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-white shadow-sm">
                      <Users
                        size={15}
                        className="text-gray-600"
                      />
                    </div>

                    <div>
                      <p className="text-xs font-semibold text-gray-800">
                        People
                      </p>

                      <p className="text-[11px] text-gray-400">
                        Users currently visible to you
                      </p>
                    </div>
                  </div>

                  <span className="text-sm font-semibold text-gray-900">
                    {usersQ.isLoading
                      ? '…'
                      : usersQ.data?.length ??
                        peopleStats.reduce(
                          (sum, item) =>
                            sum +
                            Number(item.value || 0),
                          0,
                        )}
                  </span>
                </div>

                <div className="flex items-center justify-between rounded-xl bg-gray-50 px-4 py-3">
                  <div className="flex items-center gap-3">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-white shadow-sm">
                      <Activity
                        size={15}
                        className="text-gray-600"
                      />
                    </div>

                    <div>
                      <p className="text-xs font-semibold text-gray-800">
                        Platform access
                      </p>

                      <p className="text-[11px] text-gray-400">
                        Role-based workspace access
                      </p>
                    </div>
                  </div>

                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold uppercase tracking-wider text-emerald-600">
                    <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
                    Operational
                  </span>
                </div>
              </div>
            </div>
          </div>
        </section>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* LOWER INFORMATION BAR                                             */}
      {/* ------------------------------------------------------------------ */}

      <section className="rounded-2xl border border-gray-200 bg-gray-950 px-6 py-5 text-white lg:px-7">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <div className="flex items-center gap-2">
              <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-white/10">
                <Activity size={15} />
              </div>

              <p className="text-sm font-semibold">
                PAISA workspace
              </p>
            </div>

            <p className="mt-1 pl-10 text-xs text-gray-400">
              Everything you need to manage your day is available from the navigation.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Link
              to="/dashboard/announcements"
              className="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-xs font-medium text-gray-200 transition hover:bg-white/10"
            >
              <Megaphone size={14} />
              Announcements
            </Link>

            {role === 'admin' && (
              <Link
                to="/dashboard/users"
                className="inline-flex items-center gap-2 rounded-xl bg-white px-3 py-2 text-xs font-semibold text-gray-950 transition hover:bg-gray-100"
              >
                <Users size={14} />
                Manage users
              </Link>
            )}

            {isSuperAdmin && (
              <Link
                to="/dashboard/organizations"
                className="inline-flex items-center gap-2 rounded-xl bg-white px-3 py-2 text-xs font-semibold text-gray-950 transition hover:bg-gray-100"
              >
                <Building2 size={14} />
                Manage organizations
              </Link>
            )}
          </div>
        </div>
      </section>
    </div>
  )
}

import { useMemo, useState } from 'react'
import {
  Layers,
  Plus,
  Trash2,
  Pencil,
  Search,
  MoreHorizontal,
  Users,
  Building2,
  ChevronDown,
  X,
  Check,
} from 'lucide-react'

import {
  useGetDepartmentsQuery,
  useCreateDepartmentMutation,
  useUpdateDepartmentMutation,
  useDeleteDepartmentMutation,
} from '@/features/departments/departmentsApi'

import { useGetUsersQuery, rid } from '@/features/users/usersApi'
import { useAppSelector } from '@/app/store'

import PageHeader from '@/components/ui/PageHeader'
import { LoadingGrid, ErrorState, EmptyState } from '@/components/ui/StateViews'
import Button from '@/components/ui/button'
import Badge from '@/components/ui/badge'
import Modal from '@/components/ui/Modal'

type DepartmentForm = {
  name: string
  code: string
  description: string
  head: string
  status: 'active' | 'inactive'
}

export default function DepartmentsPage() {
  const user = useAppSelector((s) => s.auth.user)

  const canManage = ['super_admin', 'admin', 'hr'].includes(
    user?.role ?? '',
  )

  const {
    data: departments = [],
    isLoading,
    isError,
    refetch,
  } = useGetDepartmentsQuery()

  const { data: staff = [] } = useGetUsersQuery()

  const [createDepartment, { isLoading: createPending }] =
    useCreateDepartmentMutation()

  const [updateDepartment, { isLoading: updatePending }] =
    useUpdateDepartmentMutation()

  const [deleteDepartment, { isLoading: deletePending }] =
    useDeleteDepartmentMutation()

  const [showModal, setShowModal] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)

  const [menuId, setMenuId] = useState<string | null>(null)
  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'inactive'>(
    'all',
  )

  const [error, setError] = useState('')

  const [form, setForm] = useState<DepartmentForm>({
    name: '',
    code: '',
    description: '',
    head: '',
    status: 'active',
  })

  const filteredDepartments = useMemo(() => {
    const query = search.trim().toLowerCase()

    return departments.filter((department) => {
      const matchesSearch =
        !query ||
        department.name.toLowerCase().includes(query) ||
        department.code?.toLowerCase().includes(query) ||
        department.description?.toLowerCase().includes(query)

      const matchesStatus =
        statusFilter === 'all' || department.status === statusFilter

      return matchesSearch && matchesStatus
    })
  }, [departments, search, statusFilter])

  const resetForm = () => {
    setForm({
      name: '',
      code: '',
      description: '',
      head: '',
      status: 'active',
    })

    setEditingId(null)
    setError('')
  }

  const openCreate = () => {
    resetForm()
    setShowModal(true)
  }

  const openEdit = (department: (typeof departments)[number]) => {
    setEditingId(department.publicId ?? department._id)

    setForm({
      name: department.name ?? '',
      code: department.code ?? '',
      description: department.description ?? '',
      head:
        typeof department.head === 'object' && department.head
          ? rid(department.head as any)
          : typeof department.head === 'string'
            ? department.head
            : '',
      status: department.status ?? 'active',
    })

    setError('')
    setMenuId(null)
    setShowModal(true)
  }

  const closeModal = () => {
    if (createPending || updatePending) return

    setShowModal(false)
    resetForm()
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!form.name.trim()) {
      setError('Department name is required')
      return
    }

    setError('')

    try {
      const payload = {
        name: form.name.trim(),
        code: form.code.trim() || undefined,
        description: form.description.trim() || undefined,
        head: form.head || undefined,
        ...(editingId ? { status: form.status } : {}),
      }

      if (editingId) {
        await updateDepartment({
          id: editingId,
          payload,
        }).unwrap()
      } else {
        await createDepartment(payload).unwrap()
      }

      setShowModal(false)
      resetForm()
    } catch (e) {
      const err = e as { data?: { message?: string }; error?: { data?: { message?: string } } }
      setError(
        err?.data?.message ??
          err?.error?.data?.message ??
          (editingId
            ? 'Failed to update department'
            : 'Failed to create department'),
      )
    }
  }

  const handleDelete = async (id: string) => {
    setMenuId(null)

    const confirmed = window.confirm(
      'Delete this department? This action cannot be undone.',
    )

    if (!confirmed) return

    try {
      await deleteDepartment(id).unwrap()
    } catch (e) {
      const err = e as { data?: { message?: string }; error?: { data?: { message?: string } } }
      setError(
        err?.data?.message ??
          err?.error?.data?.message ??
          'Failed to delete department',
      )
    }
  }

  return (
    <div className="min-h-screen bg-[#f6f6f7]">
      <div className="mx-auto max-w-[1500px] px-6 py-7 lg:px-8">
        <PageHeader
          title="Departments"
          subtitle="Manage your organization's teams, structure and department heads"
          actions={
            canManage ? (
              <Button onClick={openCreate}>
                <Plus size={16} />
                New department
              </Button>
            ) : undefined
          }
        />

        {/* TOP SUMMARY */}
        <div className="mt-7 grid grid-cols-1 gap-4 md:grid-cols-3">
          <SummaryCard
            icon={<Building2 size={18} />}
            label="Total departments"
            value={departments.length}
            description="Across your organization"
          />

          <SummaryCard
            icon={<Check size={18} />}
            label="Active"
            value={departments.filter((d) => d.status === 'active').length}
            description="Currently operating"
          />

          <SummaryCard
            icon={<Users size={18} />}
            label="Department heads"
            value={
              departments.filter(
                (d) => typeof d.head === 'object' && d.head,
              ).length
            }
            description="Assigned department heads"
          />
        </div>

        {/* TOOLBAR */}
        <div className="mt-7 rounded-2xl border border-gray-200 bg-white shadow-sm">
          <div className="flex flex-col gap-4 p-4 lg:flex-row lg:items-center lg:justify-between">
            <div className="relative w-full lg:max-w-md">
              <Search
                size={17}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />

              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search departments..."
                className="h-10 w-full rounded-xl border border-gray-200 bg-gray-50 pl-10 pr-10 text-sm text-gray-900 outline-none transition placeholder:text-gray-400 focus:border-gray-400 focus:bg-white"
              />

              {search && (
                <button
                  onClick={() => setSearch('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-700"
                >
                  <X size={15} />
                </button>
              )}
            </div>

            <div className="flex items-center gap-2">
              <div className="flex rounded-xl border border-gray-200 bg-gray-50 p-1">
                {(['all', 'active', 'inactive'] as const).map((status) => (
                  <button
                    key={status}
                    onClick={() => setStatusFilter(status)}
                    className={[
                      'rounded-lg px-3 py-1.5 text-xs font-medium capitalize transition',
                      statusFilter === status
                        ? 'bg-white text-gray-900 shadow-sm'
                        : 'text-gray-500 hover:text-gray-900',
                    ].join(' ')}
                  >
                    {status}
                  </button>
                ))}
              </div>

              {canManage && (
                <Button onClick={openCreate}>
                  <Plus size={15} />
                  Add
                </Button>
              )}
            </div>
          </div>

          <div className="border-t border-gray-100 px-4 py-3">
            <div className="flex items-center justify-between text-xs text-gray-500">
              <span>
                {filteredDepartments.length}{' '}
                {filteredDepartments.length === 1
                  ? 'department'
                  : 'departments'}
              </span>

              {(search || statusFilter !== 'all') && (
                <button
                  onClick={() => {
                    setSearch('')
                    setStatusFilter('all')
                  }}
                  className="font-medium text-gray-900 hover:underline"
                >
                  Clear filters
                </button>
              )}
            </div>
          </div>
        </div>

        {/* CONTENT */}
        <div className="mt-4">
          {isLoading ? (
            <LoadingGrid />
          ) : isError ? (
            <ErrorState onRetry={() => refetch()} />
          ) : !filteredDepartments.length ? (
            <div className="rounded-2xl border border-gray-200 bg-white py-20">
              <EmptyState
                icon={<Layers size={42} />}
                title={
                  search || statusFilter !== 'all'
                    ? 'No departments found'
                    : 'No departments yet'
                }
                hint={
                  search || statusFilter !== 'all'
                    ? 'Try changing your search or filters'
                    : canManage
                      ? 'Create your first department to structure your organization'
                      : 'Departments will appear here'
                }
                action={
                  canManage && !search && statusFilter === 'all' ? (
                    <Button onClick={openCreate}>
                      <Plus size={16} />
                      New department
                    </Button>
                  ) : undefined
                }
              />
            </div>
          ) : (
            <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm">
              {/* TABLE HEADER */}
              <div className="hidden grid-cols-[minmax(280px,2fr)_140px_minmax(180px,1fr)_130px_60px] border-b border-gray-100 bg-gray-50/70 px-5 py-3 text-[11px] font-semibold uppercase tracking-wide text-gray-400 md:grid">
                <span>Department</span>
                <span>Status</span>
                <span>Head</span>
                <span>Created</span>
                <span />
              </div>

              {/* ROWS */}
              <div className="divide-y divide-gray-100">
                {filteredDepartments.map((department) => {
                  const id = department.publicId ?? department._id

                  const head =
                    typeof department.head === 'object' && department.head
                      ? department.head
                      : null

                  return (
                    <div
                      key={id}
                      className="group relative grid gap-4 px-5 py-5 transition hover:bg-gray-50/60 md:grid-cols-[minmax(280px,2fr)_140px_minmax(180px,1fr)_130px_60px] md:items-center"
                    >
                      {/* DEPARTMENT */}
                      <div className="flex min-w-0 items-center gap-4">
                        <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-gray-100 text-gray-700">
                          <Building2 size={19} />
                        </div>

                        <div className="min-w-0">
                          <div className="flex items-center gap-2">
                            <h3 className="truncate text-sm font-semibold text-gray-900">
                              {department.name}
                            </h3>

                            {department.code && (
                              <span className="rounded-md bg-gray-100 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-gray-500">
                                {department.code}
                              </span>
                            )}
                          </div>

                          <p className="mt-1 truncate text-xs text-gray-500">
                            {department.description || 'No description added'}
                          </p>
                        </div>
                      </div>

                      {/* STATUS */}
                      <div>
                        <Badge
                          color={
                            department.status === 'active'
                              ? 'green'
                              : 'gray'
                          }
                        >
                          {department.status}
                        </Badge>
                      </div>

                      {/* HEAD */}
                      <div className="flex min-w-0 items-center gap-3">
                        {head ? (
                          <>
                            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-gray-900 text-xs font-semibold text-white">
                              {head.name?.charAt(0)?.toUpperCase() ?? '?'}
                            </div>

                            <div className="min-w-0">
                              <p className="truncate text-sm font-medium text-gray-800">
                                {head.name}
                              </p>
                              <p className="truncate text-xs text-gray-400">
                                {head.email}
                              </p>
                            </div>
                          </>
                        ) : (
                          <span className="text-sm text-gray-400">
                            No head assigned
                          </span>
                        )}
                      </div>

                      {/* DATE */}
                      <div>
                        <p className="text-xs text-gray-400">Created</p>
                        <p className="mt-1 text-sm text-gray-700">
                          {department.createdAt
                            ? new Date(
                                department.createdAt,
                              ).toLocaleDateString('en-IN', {
                                day: '2-digit',
                                month: 'short',
                                year: 'numeric',
                              })
                            : '—'}
                        </p>
                      </div>

                      {/* ACTIONS */}
                      <div className="relative flex justify-end">
                        {canManage && (
                          <>
                            <button
                              onClick={() =>
                                setMenuId(
                                  menuId === id ? null : id,
                                )
                              }
                              className="flex h-9 w-9 items-center justify-center rounded-lg text-gray-400 transition hover:bg-gray-100 hover:text-gray-900"
                            >
                              <MoreHorizontal size={18} />
                            </button>

                            {menuId === id && (
                              <>
                                <button
                                  className="fixed inset-0 z-10 cursor-default"
                                  onClick={() => setMenuId(null)}
                                />

                                <div className="absolute right-0 top-10 z-20 w-44 overflow-hidden rounded-xl border border-gray-200 bg-white p-1.5 shadow-xl">
                                  <button
                                    onClick={() =>
                                      openEdit(department)
                                    }
                                    className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-gray-700 hover:bg-gray-50"
                                  >
                                    <Pencil size={15} />
                                    Edit department
                                  </button>

                                  <div className="my-1 border-t border-gray-100" />

                                  <button
                                    onClick={() =>
                                      handleDelete(id)
                                    }
                                    disabled={deletePending}
                                    className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm text-red-600 hover:bg-red-50 disabled:opacity-50"
                                  >
                                    <Trash2 size={15} />
                                    Delete department
                                  </button>
                                </div>
                              </>
                            )}
                          </>
                        )}
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          )}
        </div>

        {/* CREATE / EDIT MODAL */}
        <Modal
          open={showModal}
          onClose={closeModal}
          title={editingId ? 'Edit department' : 'New department'}
          size="md"
        >
          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="rounded-xl bg-gray-50 p-4">
              <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gray-900 text-white">
                  <Building2 size={18} />
                </div>

                <div>
                  <p className="text-sm font-semibold text-gray-900">
                    {editingId
                      ? 'Update department'
                      : 'Create department'}
                  </p>

                  <p className="text-xs text-gray-500">
                    Manage the department structure and ownership.
                  </p>
                </div>
              </div>
            </div>

            {/* NAME + CODE */}
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <FormField label="Department name" required>
                <input
                  value={form.name}
                  onChange={(e) =>
                    setForm((prev) => ({
                      ...prev,
                      name: e.target.value,
                    }))
                  }
                  required
                  placeholder="e.g. Engineering"
                  className="form-input"
                />
              </FormField>

              <FormField label="Code">
                <input
                  value={form.code}
                  onChange={(e) =>
                    setForm((prev) => ({
                      ...prev,
                      code: e.target.value,
                    }))
                  }
                  placeholder="e.g. ENG"
                  className="form-input uppercase"
                />
              </FormField>
            </div>

            {/* DESCRIPTION */}
            <FormField label="Description">
              <textarea
                value={form.description}
                onChange={(e) =>
                  setForm((prev) => ({
                    ...prev,
                    description: e.target.value,
                  }))
                }
                rows={3}
                placeholder="What does this department handle?"
                className="form-input resize-none"
              />
            </FormField>

            {/* HEAD */}
            <FormField label="Department head">
              <div className="relative">
                <select
                  value={form.head}
                  onChange={(e) =>
                    setForm((prev) => ({
                      ...prev,
                      head: e.target.value,
                    }))
                  }
                  className="form-input appearance-none pr-10"
                >
                  <option value="">Assign later</option>

                  {staff.map((u) => (
                    <option key={rid(u)} value={rid(u)}>
                      {u.name} — {u.role}
                    </option>
                  ))}
                </select>

                <ChevronDown
                  size={16}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                />
              </div>
            </FormField>

            {/* STATUS */}
            {editingId && (
              <FormField label="Status">
                <div className="grid grid-cols-2 gap-2">
                  {(['active', 'inactive'] as const).map((status) => (
                    <button
                      type="button"
                      key={status}
                      onClick={() =>
                        setForm((prev) => ({
                          ...prev,
                          status,
                        }))
                      }
                      className={[
                        'rounded-xl border px-4 py-3 text-left text-sm transition',
                        form.status === status
                          ? 'border-gray-900 bg-gray-50 text-gray-900'
                          : 'border-gray-200 text-gray-500 hover:bg-gray-50',
                      ].join(' ')}
                    >
                      <div className="flex items-center justify-between">
                        <span className="font-medium capitalize">
                          {status}
                        </span>

                        {form.status === status && (
                          <Check size={16} />
                        )}
                      </div>
                    </button>
                  ))}
                </div>
              </FormField>
            )}

            {error && (
              <div className="rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm text-red-600">
                {error}
              </div>
            )}

            {/* FOOTER */}
            <div className="flex items-center justify-between border-t border-gray-100 pt-5">
              <button
                type="button"
                onClick={closeModal}
                className="rounded-xl px-4 py-2.5 text-sm font-medium text-gray-500 transition hover:bg-gray-100 hover:text-gray-900"
              >
                Cancel
              </button>

              <Button
                type="submit"
                loading={createPending || updatePending}
              >
                {editingId ? (
                  <>
                    <Check size={16} />
                    Save changes
                  </>
                ) : (
                  <>
                    <Plus size={16} />
                    Create department
                  </>
                )}
              </Button>
            </div>
          </form>
        </Modal>
      </div>

      <style>{`
        .form-input {
          width: 100%;
          border-radius: 0.75rem;
          border: 1px solid rgb(229 231 235);
          background: white;
          padding: 0.65rem 0.8rem;
          font-size: 0.875rem;
          color: rgb(17 24 39);
          outline: none;
          transition: all 150ms ease;
        }

        .form-input::placeholder {
          color: rgb(156 163 175);
        }

        .form-input:focus {
          border-color: rgb(17 24 39);
          box-shadow: 0 0 0 3px rgb(17 24 39 / 0.05);
        }
      `}</style>
    </div>
  )
}

function SummaryCard({
  icon,
  label,
  value,
  description,
}: {
  icon: React.ReactNode
  label: string
  value: number
  description: string
}) {
  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-xs font-medium text-gray-500">{label}</p>

          <p className="mt-2 text-2xl font-semibold tracking-tight text-gray-900">
            {value}
          </p>

          <p className="mt-1 text-xs text-gray-400">{description}</p>
        </div>

        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-gray-100 text-gray-600">
          {icon}
        </div>
      </div>
    </div>
  )
}

function FormField({
  label,
  required,
  children,
}: {
  label: string
  required?: boolean
  children: React.ReactNode
}) {
  return (
    <div>
      <label className="mb-1.5 block text-xs font-semibold text-gray-700">
        {label}
        {required && <span className="ml-1 text-red-500">*</span>}
      </label>

      {children}
    </div>
  )
}

import { useState } from 'react'
import { FileText, Plus, Check, X, Ban } from 'lucide-react'

import {
  useGetLeavesQuery,
  useApplyLeaveMutation,
  useUpdateLeaveStatusMutation,
  useCancelLeaveMutation,
  type Leave,
} from '@/features/leaves/leavesApi'
import { useAppSelector } from '@/app/store'
import { rid } from '@/features/users/usersApi'
import PageHeader from '@/components/ui/PageHeader'
import { LoadingList, ErrorState, EmptyState } from '@/components/ui/StateViews'
import Button from '@/components/ui/button'
import Badge from '@/components/ui/badge'
import Modal from '@/components/ui/Modal'

const STATUS_COLOR: Record<string, 'yellow' | 'green' | 'red' | 'gray'> = {
  pending: 'yellow', approved: 'green', rejected: 'red', cancelled: 'gray',
}

const TYPES = ['casual', 'sick', 'earned', 'unpaid', 'other']

function ApplyLeaveModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [applyLeave, { isLoading }] = useApplyLeaveMutation()
  const [error, setError] = useState('')

  const [type, setType] = useState('casual')
  const [startDate, setStartDate] = useState('')
  const [endDate, setEndDate] = useState('')
  const [reason, setReason] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    try {
      await applyLeave({ type: type as any, startDate, endDate, reason }).unwrap()
      onClose()
    } catch (e: any) {
      setError(e?.data?.message ?? 'Failed to apply for leave')
    }
  }

  return (
    <Modal open={open} onClose={onClose} title="Apply for Leave" size="md">
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="mb-1 block text-sm font-medium text-gray-700">Leave Type *</label>
          <select value={type} onChange={(e) => setType(e.target.value)}
            className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm capitalize outline-none focus:border-black">
            {TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="mb-1 block text-sm font-medium text-gray-700">From *</label>
            <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} required
              className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black" />
          </div>
          <div>
            <label className="mb-1 block text-sm font-medium text-gray-700">To *</label>
            <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} required min={startDate}
              className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black" />
          </div>
        </div>

        <div>
          <label className="mb-1 block text-sm font-medium text-gray-700">Reason *</label>
          <textarea value={reason} onChange={(e) => setReason(e.target.value)} required rows={3}
            placeholder="Why do you need this leave?"
            className="w-full resize-none rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black" />
        </div>

        {error && <div className="rounded-xl bg-red-50 px-4 py-3 text-sm text-red-600">{error}</div>}

        <div className="flex justify-end gap-3 border-t pt-4">
          <Button variant="secondary" type="button" onClick={onClose}>Cancel</Button>
          <Button type="submit" loading={isLoading}>Submit Application</Button>
        </div>
      </form>
    </Modal>
  )
}

export default function LeavesPage() {
  const user = useAppSelector((s) => s.auth.user)
  const isApprover = user?.role === 'super_admin' || user?.role === 'admin' || user?.role === 'hr'

  const { data: leaves, isLoading, isError, refetch } = useGetLeavesQuery()
  const [updateStatus] = useUpdateLeaveStatusMutation()
  const [cancelLeave] = useCancelLeaveMutation()
  const [showApply, setShowApply] = useState(false)

  const pending = (leaves ?? []).filter((l) => l.status === 'pending')
  const other = (leaves ?? []).filter((l) => l.status !== 'pending')

  const person = (l: Leave) => (typeof l.userId === 'object' ? l.userId?.name ?? '—' : '—')

  const renderRow = (l: Leave) => (
    <div key={rid(l)} className="flex items-center justify-between gap-3 border-b border-gray-50 px-5 py-3 last:border-0">
      <div className="min-w-0">
        <p className="text-sm font-medium text-gray-800">
          {isApprover ? person(l) : `${l.type} leave`}{' '}
          <span className="font-normal text-gray-400">· {l.days} day{l.days !== 1 ? 's' : ''}</span>
        </p>
        <p className="truncate text-xs text-gray-400">
          {new Date(l.startDate).toLocaleDateString()} → {new Date(l.endDate).toLocaleDateString()} · {l.reason}
        </p>
      </div>
      <div className="flex flex-shrink-0 items-center gap-2">
        <Badge color={STATUS_COLOR[l.status]}>{l.status}</Badge>
        {isApprover && l.status === 'pending' && (
          <>
            <button onClick={() => updateStatus({ id: rid(l), status: 'approved' })}
              className="rounded-lg p-1.5 text-green-600 transition hover:bg-green-50" title="Approve">
              <Check size={16} />
            </button>
            <button onClick={() => updateStatus({ id: rid(l), status: 'rejected', rejectionReason: 'Not approved' })}
              className="rounded-lg p-1.5 text-red-500 transition hover:bg-red-50" title="Reject">
              <X size={16} />
            </button>
          </>
        )}
        {!isApprover && l.status === 'pending' && (typeof l.userId === 'object' ? user?.publicId === l.userId.publicId || user?._id === l.userId._id : user?.publicId === l.userId) && (
          <button onClick={() => cancelLeave(rid(l))}
            className="rounded-lg p-1.5 text-gray-400 transition hover:bg-gray-100" title="Cancel">
            <Ban size={15} />
          </button>
        )}
      </div>
    </div>
  )

  return (
    <div className="space-y-6">
      <PageHeader
        title={isApprover ? 'Leave Requests' : 'My Leaves'}
        subtitle={isApprover ? 'Review and approve leave applications' : 'Apply for and track your leaves'}
        actions={<Button onClick={() => setShowApply(true)}><Plus size={16} /> Apply for Leave</Button>}
      />

      {isLoading ? (
        <LoadingList rows={4} />
      ) : isError ? (
        <ErrorState onRetry={() => refetch()} />
      ) : !leaves?.length ? (
        <EmptyState
          icon={<FileText size={48} />}
          title="No leave requests"
          hint={isApprover ? 'Nothing to review right now' : 'You have not applied for any leave'}
          action={<Button onClick={() => setShowApply(true)}><Plus size={16} /> Apply for Leave</Button>}
        />
      ) : (
        <>
          {isApprover && pending.length > 0 && (
            <div>
              <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-gray-400">
                Pending ({pending.length})
              </p>
              <div className="rounded-2xl bg-white shadow-sm">{pending.map(renderRow)}</div>
            </div>
          )}
          <div>
            {isApprover && pending.length > 0 && (
              <p className="mb-2 text-xs font-semibold uppercase tracking-wider text-gray-400">History</p>
            )}
            <div className="rounded-2xl bg-white shadow-sm">{(isApprover ? other : leaves).map(renderRow)}</div>
          </div>
        </>
      )}

      {showApply && <ApplyLeaveModal open={showApply} onClose={() => setShowApply(false)} />}
    </div>
  )
}

import { useState } from 'react'
import { BookMarked, Plus, Trash2, ExternalLink, FileVideo, FileText, Link2 } from 'lucide-react'
import {
  useGetMaterialsQuery,
  useCreateMaterialMutation,
  useDeleteMaterialMutation,
} from '@/features/assignments/assignmentsApi'
import { useGetClassesQuery } from '@/features/classes/classesApi'
import { rid } from '@/features/users/usersApi'
import { useAppSelector } from '@/app/store'
import PageHeader from '@/components/ui/PageHeader'
import { LoadingList, ErrorState, EmptyState } from '@/components/ui/StateViews'
import Button from '@/components/ui/button'
import Badge from '@/components/ui/badge'
import Modal from '@/components/ui/Modal'

const TYPE_ICON: Record<string, any> = {
  pdf: FileText, video: FileVideo, link: Link2, other: BookMarked,
}

export default function MaterialsPage() {
  const user = useAppSelector((s) => s.auth.user)
  const canUpload = ['super_admin', 'admin', 'teacher'].includes(user?.role ?? '')

  const { data: materials, isLoading, isError, refetch } = useGetMaterialsQuery()
  const { data: classes } = useGetClassesQuery(undefined, { skip: !canUpload })

  const [createMaterial, { isLoading: createPending }] = useCreateMaterialMutation()
  const [deleteMaterial] = useDeleteMaterialMutation()

  const [showCreate, setShowCreate] = useState(false)
  const [error, setError] = useState('')
  const [title, setTitle] = useState('')
  const [url, setUrl] = useState('')
  const [subject, setSubject] = useState('')
  const [type, setType] = useState('link')
  const [classId, setClassId] = useState('')

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    try {
      await createMaterial({
        title, url, subject: subject || undefined, type,
        classId: classId || undefined,
      }).unwrap()
      setShowCreate(false)
      setTitle(''); setUrl(''); setSubject('')
    } catch (e) {
      setError((e as { data?: { message?: string } })?.data?.message ?? 'Failed to upload material')
    }
  }

  return (
    <div className="space-y-6">
      <PageHeader
        title="Study Materials"
        subtitle={canUpload ? 'Share resources with your classes' : 'Resources shared by your teachers'}
        actions={canUpload ? <Button onClick={() => setShowCreate(true)}><Plus size={16} /> Add Material</Button> : undefined}
      />

      {isLoading ? (
        <LoadingList rows={5} />
      ) : isError ? (
        <ErrorState onRetry={() => refetch()} />
      ) : !materials?.length ? (
        <EmptyState
          icon={<BookMarked size={48} />}
          title="No materials yet"
          hint={canUpload ? 'Share the first resource' : 'Materials will appear here'}
          action={canUpload ? <Button onClick={() => setShowCreate(true)}><Plus size={16} /> Add Material</Button> : undefined}
        />
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {materials.map((m) => {
            const Icon = TYPE_ICON[m.type ?? 'other'] ?? BookMarked
            const clsName = typeof m.classId === 'object' ? m.classId?.name : null
            return (
              <div key={m.publicId ?? m._id} className="group rounded-2xl bg-white p-5 shadow-sm">
                <div className="mb-3 flex items-start justify-between">
                  <div className="rounded-xl bg-blue-50 p-2.5 text-blue-600"><Icon size={18} /></div>
                  {canUpload && (
                    <button onClick={() => deleteMaterial(m.publicId ?? m._id)}
                      className="rounded-lg p-1.5 text-red-400 opacity-0 transition hover:bg-red-50 group-hover:opacity-100" title="Delete">
                      <Trash2 size={14} />
                    </button>
                  )}
                </div>
                <h3 className="font-semibold text-gray-900">{m.title}</h3>
                {m.description && <p className="mt-1 line-clamp-2 text-xs text-gray-400">{m.description}</p>}
                <div className="mt-3 flex items-center justify-between">
                  <div className="flex gap-1.5">
                    <Badge color="blue">{m.type ?? 'link'}</Badge>
                    {clsName && <Badge color="gray">{clsName}</Badge>}
                  </div>
                  <a href={m.url} target="_blank" rel="noopener noreferrer"
                    className="flex items-center gap-1 text-xs font-medium text-black hover:underline">
                    Open <ExternalLink size={11} />
                  </a>
                </div>
              </div>
            )
          })}
        </div>
      )}

      <Modal open={showCreate} onClose={() => setShowCreate(false)} title="Add Study Material" size="md">
        <form onSubmit={handleCreate} className="space-y-4">
          <div>
            <label className="mb-1 block text-sm font-medium text-gray-700">Title *</label>
            <input value={title} onChange={(e) => setTitle(e.target.value)} required placeholder="e.g. Algebra Worksheet 1"
              className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black" />
          </div>
          <div>
            <label className="mb-1 block text-sm font-medium text-gray-700">URL *</label>
            <input value={url} onChange={(e) => setUrl(e.target.value)} required type="url" placeholder="https://..."
              className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">Type</label>
              <select value={type} onChange={(e) => setType(e.target.value)}
                className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black">
                <option value="link">Link</option>
                <option value="pdf">PDF</option>
                <option value="video">Video</option>
                <option value="other">Other</option>
              </select>
            </div>
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">Class</label>
              <select value={classId} onChange={(e) => setClassId(e.target.value)}
                className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black">
                <option value="">— General —</option>
                {(classes ?? []).map((c) => (
                  <option key={rid(c)} value={rid(c)}>{c.name}</option>
                ))}
              </select>
            </div>
          </div>
          <div>
            <label className="mb-1 block text-sm font-medium text-gray-700">Subject</label>
            <input value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="e.g. Mathematics"
              className="w-full rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-black" />
          </div>
          {error && <div className="rounded-xl bg-red-50 px-4 py-3 text-sm text-red-600">{error}</div>}
          <div className="flex justify-end gap-3 border-t pt-4">
            <Button variant="secondary" type="button" onClick={() => setShowCreate(false)}>Cancel</Button>
            <Button type="submit" loading={createPending}>Add</Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

import { useState } from 'react'
import { useParams, Link, useNavigate } from 'react-router-dom'
import {
  ArrowLeft, Building2, Globe, Mail, MapPin, Phone, Users, Layers,
  Network, ShieldCheck, Calendar, ArrowUp,
} from 'lucide-react'
import {
  useGetOrganizationsQuery,
} from '@/features/organizations/organizationsApi'
import { useGetUsersQuery, rid } from '@/features/users/usersApi'
import { useGetDepartmentsQuery } from '@/features/departments/departmentsApi'
import { useAppSelector } from '@/app/store'
import { LoadingList, ErrorState } from '@/components/ui/StateViews'
import Badge from '@/components/ui/badge'
import StatCard from '@/components/ui/StatCard'

const PLAN_COLOR = { free: 'gray', pro: 'blue', enterprise: 'purple' } as const
const STATUS_COLOR = { active: 'green', inactive: 'yellow', suspended: 'red' } as const

/**
 * Modern org chart — clean connector lines, avatar cards, expand/collapse.
 * Hierarchy: Admin → (HR | Teachers) → (Employees | Students)
 */
const ROLE_THEME: Record<string, { chip: string; ring: string; dot: string; label: string }> = {
  admin: { chip: 'bg-blue-600', ring: 'ring-blue-200', dot: 'bg-blue-500', label: 'Leadership' },
  hr: { chip: 'bg-amber-500', ring: 'ring-amber-200', dot: 'bg-amber-500', label: 'Human Resources' },
  teacher: { chip: 'bg-teal-600', ring: 'ring-teal-200', dot: 'bg-teal-500', label: 'Faculty' },
  employee: { chip: 'bg-cyan-600', ring: 'ring-cyan-200', dot: 'bg-cyan-500', label: 'Employees' },
  student: { chip: 'bg-indigo-600', ring: 'ring-indigo-200', dot: 'bg-indigo-500', label: 'Students' },
}

function PersonCard({ p, accent }: { p: any; accent: string }) {
  return (
    <Link
      to={`/dashboard/users/${p.publicId ?? p._id}`}
      className="group flex w-44 items-center gap-2.5 rounded-2xl border border-gray-100 bg-white p-2.5 shadow-sm transition-all hover:-translate-y-0.5 hover:border-gray-200 hover:shadow-md"
    >
      <div className={`flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-xl bg-gradient-to-br ${accent} text-xs font-bold text-white`}>
        {p.name?.[0]?.toUpperCase() ?? '?'}
      </div>
      <div className="min-w-0">
        <p className="truncate text-xs font-semibold text-gray-800 group-hover:text-black">{p.name}</p>
        <p className="truncate text-[10px] text-gray-400">{p.userCode ?? p.email}</p>
      </div>
    </Link>
  )
}

function RoleGroup({
  role, people, max = 4,
}: {
  role: string
  people: any[]
  max?: number
}) {
  const [expanded, setExpanded] = useState(false)
  const theme = ROLE_THEME[role]
  if (!people.length) return null

  const shown = expanded ? people : people.slice(0, max)
  const hidden = people.length - max

  return (
    <div className="flex flex-col items-center">
      {/* Level chip */}
      <div className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-white ${theme.chip}`}>
        <span className={`h-1.5 w-1.5 rounded-full bg-white/70`} />
        {theme.label} · {people.length}
      </div>

      {/* Connector stem */}
      <div className="h-4 w-px bg-gradient-to-b from-gray-200 to-gray-100" />

      {/* People cards */}
      <div className="flex max-w-full flex-wrap justify-center gap-2">
        {shown.map((p) => (
          <PersonCard key={p.publicId ?? p._id} p={p} accent={
            role === 'admin' ? 'from-blue-500 to-blue-700'
            : role === 'hr' ? 'from-amber-400 to-amber-600'
            : role === 'teacher' ? 'from-teal-500 to-teal-700'
            : role === 'employee' ? 'from-cyan-500 to-cyan-700'
            : 'from-indigo-500 to-indigo-700'
          } />
        ))}
      </div>

      {/* Expand / collapse */}
      {hidden > 0 && !expanded && (
        <button
          onClick={() => setExpanded(true)}
          className="mt-2 rounded-full bg-gray-50 px-3 py-1 text-[11px] font-medium text-gray-500 ring-1 ring-gray-100 transition hover:bg-gray-100 hover:text-gray-700"
        >
          +{hidden} more
        </button>
      )}
      {expanded && people.length > max && (
        <button
          onClick={() => setExpanded(false)}
          className="mt-2 rounded-full bg-gray-50 px-3 py-1 text-[11px] font-medium text-gray-500 ring-1 ring-gray-100 transition hover:bg-gray-100 hover:text-gray-700"
        >
          Show less
        </button>
      )}
    </div>
  )
}

function OrgChart({ members }: { members: any[] }) {
  const byRole = (r: string) => members.filter((m) => m.role === r)
  const admins = byRole('admin')
  const midLayer = [
    { role: 'hr', people: byRole('hr') },
    { role: 'teacher', people: byRole('teacher') },
  ].filter((g) => g.people.length > 0)
  const baseLayer = [
    { role: 'employee', people: byRole('employee') },
    { role: 'student', people: byRole('student') },
  ].filter((g) => g.people.length > 0)

  if (!members.length) {
    return (
      <div className="rounded-3xl border border-dashed border-gray-200 bg-white py-16 text-center">
        <Network size={40} className="mx-auto mb-3 text-gray-200" />
        <p className="text-sm text-gray-400">No members yet — the chart will build itself as people join</p>
      </div>
    )
  }

  return (
    <div className="overflow-x-auto rounded-3xl border border-gray-100 bg-gradient-to-b from-gray-50 via-white to-gray-50 p-8 shadow-sm">
      <div className="mx-auto flex min-w-fit flex-col items-center">
        {/* ROOT — the organization */}
        <div className="flex flex-col items-center">
          <div className="flex items-center gap-2.5 rounded-2xl bg-gray-900 px-5 py-2.5 shadow-lg">
            <Building2 size={15} className="text-white/80" />
            <span className="text-sm font-bold text-white">Organization</span>
            <span className="rounded-full bg-white/15 px-2 py-0.5 text-[10px] font-semibold text-white/90">
              {members.length} people
            </span>
          </div>
        </div>

        {/* Trunk down to leadership */}
        <div className="h-6 w-px bg-gradient-to-b from-gray-300 to-gray-200" />

        {/* LEVEL 1 — Admins */}
        <RoleGroup role="admin" people={admins} max={4} />

        {/* Branch to mid layer */}
        {midLayer.length > 0 && (
          <>
            <div className="h-5 w-px bg-gray-200" />
            <div className="relative flex items-start justify-center gap-16">
              {/* horizontal rail */}
              {midLayer.length > 1 && (
                <div className="absolute top-0 h-px bg-gray-200" style={{ width: `${(midLayer.length - 1) * 8}rem`, left: '50%', transform: 'translateX(-50%)' }} />
              )}
              {midLayer.map((g) => (
                <div key={g.role} className="relative flex flex-col items-center">
                  {/* drop line from rail */}
                  {midLayer.length > 1 && <div className="h-4 w-px bg-gray-200" />}
                  <RoleGroup role={g.role} people={g.people} max={4} />
                </div>
              ))}
            </div>
          </>
        )}

        {/* Branch to base layer */}
        {baseLayer.length > 0 && (
          <>
            <div className="h-5 w-px bg-gray-200" />
            <div className="relative flex items-start justify-center gap-16">
              {baseLayer.length > 1 && (
                <div className="absolute top-0 h-px bg-gray-200" style={{ width: `${(baseLayer.length - 1) * 8}rem`, left: '50%', transform: 'translateX(-50%)' }} />
              )}
              {baseLayer.map((g) => (
                <div key={g.role} className="relative flex flex-col items-center">
                  {baseLayer.length > 1 && <div className="h-4 w-px bg-gray-200" />}
                  <RoleGroup role={g.role} people={g.people} max={6} />
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

export default function OrganizationDetailPage() {
  const { id } = useParams()
  const navigate = useNavigate()
  const user = useAppSelector((s) => s.auth.user)
  const isSuperAdmin = user?.role === 'super_admin'

  const { data, isLoading, isError, refetch } = useGetOrganizationsQuery({ limit: 100 })
  const { data: members } = useGetUsersQuery()
  const { data: departments } = useGetDepartmentsQuery()

  // URL carries the org's publicId (or legacy _id) — resolve the org first,
  // then match members/departments against its real Mongo _id (instituteId
  // on users/departments stores the _id, never the publicId).
  const org = (data?.data ?? []).find((o) => rid(o) === id)
  const orgMongoId = org?._id ? String(org._id) : null

  const matchesOrg = (value: any) => {
    if (!orgMongoId) return false
    const valueId =
      typeof value === 'object' && value ? value._id ?? value : value
    return valueId != null && String(valueId) === orgMongoId
  }

  const orgMembers = (members ?? []).filter((m) => matchesOrg(m.instituteId))
  const orgDepartments = (departments ?? []).filter((d: any) => matchesOrg(d.instituteId))

