      <div className="grid gap-5 xl:grid-cols-[1.7fr_1fr]">
        <Card className="h-[390px] p-5">
          <Skeleton className="h-5 w-48" />
          <Skeleton className="mt-8 h-64 w-full" />
        </Card>
        <Card className="h-[390px] p-5">
          <Skeleton className="h-5 w-40" />
          <Skeleton className="mt-8 h-64 w-full" />
        </Card>
      </div>
