}

function MobileMenu({
  open,
  onClose,
  currentPath,
}: {
  open: boolean;
  onClose: () => void;
  currentPath: string;
}) {
  const navigate = useNavigate();
  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 lg:hidden">
      <button
        type="button"
        aria-label="Close menu"
        onClick={onClose}
        className="absolute inset-0 bg-gray-950/30 backdrop-blur-[2px]"
      />
      <div className="absolute inset-y-0 left-0 w-[290px] bg-white shadow-2xl">
        <div className="flex h-14 items-center justify-between border-b border-gray-100 px-4">
          <span className="text-sm font-black tracking-[-0.03em]">PAISA</span>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-2 text-gray-400 hover:bg-gray-100"
          >
            <X size={17} />
          </button>
        </div>
        <div className="h-[calc(100vh-56px)] overflow-y-auto p-3">
          {NAV_GROUPS.map((group) => (
            <div key={group.title} className="mb-5">
              <div className="px-3 pb-2 text-[10px] font-bold uppercase tracking-[0.16em] text-gray-400">
                {group.title}
              </div>
              <div className="space-y-1">
                {group.items.map((item) => {
                  const Icon = item.icon;
                  const active =
                    currentPath === item.path ||
                    (item.path !== "/dashboard" &&
                      currentPath.startsWith(`${item.path}/`));
                  return (
                    <button
                      key={item.path}
                      type="button"
                      onClick={() => {
                        onClose();
                        navigate(item.path);
                      }}
                      className={[
                        "flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm",
                        active
                          ? "bg-gray-950 font-medium text-white"
                          : "text-gray-600 hover:bg-gray-50",
                      ].join(" ")}
                    >
                      <Icon size={16} />
                      {item.label}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

