export default function AdminOrganizationDashboard() {
  const navigate = useNavigate();
  const currentUser = useAppSelector(
    (state: any) => state.auth.user
  ) as AnyRecord | null;

  const [mobileMenu, setMobileMenu] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [peopleSearch, setPeopleSearch] = useState("");
  const [refreshing, setRefreshing] = useState(false);

  const currentPath =
    typeof window !== "undefined"
      ? window.location.pathname
      : "/dashboard/organization";

  const organizationId = getUserOrganizationId(currentUser);

  const organizationsQuery = useGetOrganizationsQuery({
    page: 1,
    limit: 10,
  });

  const usersQuery = useGetUsersQuery({
    limit: 1000,
  } as any);

  const organizations = safeArray(
    (organizationsQuery.data as any)?.data ||
      organizationsQuery.data ||
      []
  ) as AnyRecord[];

  const users = safeArray(
    (usersQuery.data as any)?.data ||
      usersQuery.data ||
      []
  ) as DashboardUser[];

  const organization = useMemo(() => {
    if (!organizations.length) return null;

    const byPublicId = organizations.find(
      (item) =>
        organizationId &&
        String(item?.publicId) === String(organizationId)
    );
    if (byPublicId) return byPublicId;

    const byId = organizations.find(
      (item) =>
        organizationId &&
        String(item?._id) === String(organizationId)
    );
    if (byId) return byId;

    return organizations[0] || null;
  }, [organizations, organizationId]);

  const scopedUsers = useMemo(() => {
    if (!organization) return users;

    const orgId = String(
      organization?._id ||
        organization?.publicId ||
        organizationId
    );

    return users.filter((user) => {
      const userOrg =
        typeof user.instituteId === "string"
          ? user.instituteId
          : String(
              (user.instituteId as AnyRecord)?._id ||
                (user.instituteId as AnyRecord)?.publicId ||
                ""
            );

      return !userOrg || userOrg === orgId || userOrg === organizationId;
    });
  }, [users, organization, organizationId]);

  const roleCounts = useMemo(
    () => buildRoleCounts(scopedUsers),
    [scopedUsers]
  );

  const departmentCounts = useMemo(
    () => buildDepartmentCounts(scopedUsers),
    [scopedUsers]
  );

  const trend = useMemo(
    () => buildMonthTrend(scopedUsers),
    [scopedUsers]
  );

  const totalUsers = scopedUsers.length;
  const activeUsers = scopedUsers.filter(
    (user) => user.status === "active"
  ).length;

  const students = number(roleCounts.student);
  const teachers = number(roleCounts.teacher);
  const employees = number(roleCounts.employee);
  const admins = number(roleCounts.admin);
  const hrUsers = number(roleCounts.hr);

  const refresh = async () => {
    setRefreshing(true);
    try {
      await Promise.all([
        organizationsQuery.refetch(),
        usersQuery.refetch(),
      ]);
    } finally {
      window.setTimeout(() => setRefreshing(false), 400);
    }
  };

  if (
    organizationsQuery.isLoading &&
    !organizations.length
  ) {
    return <PageLoading />;
  }

  if (
    organizationsQuery.isError ||
    usersQuery.isError
  ) {
    return (
      <ErrorState
        onRetry={() => {
          void refresh();
        }}
      />
    );
  }

  if (!organization) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 p-6">
        <Card className="max-w-md p-8 text-center">
          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-gray-100 text-gray-500">
            <Building2 size={20} />
          </div>
          <h1 className="mt-5 text-lg font-semibold text-gray-950">
            No organization found
          </h1>
          <p className="mt-2 text-sm leading-6 text-gray-500">
            Your admin account is not currently associated with an
            organization.
          </p>
          <button
            type="button"
            onClick={() => navigate("/dashboard/settings")}
            className="mt-6 h-10 rounded-xl bg-gray-950 px-4 text-sm font-medium text-white"
          >
            Open settings
          </button>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f6f7f9] text-gray-950">
      <div className="flex min-h-screen">


        <div className="min-w-0 flex-1">
          <MobileTopbar
            onMenu={() => setMobileMenu(true)}
            organization={organization}
          />

          <Topbar
            organization={organization}
            currentUser={currentUser}
            onRefresh={() => {
              void refresh();
            }}
            refreshing={refreshing}
            onEdit={() => setEditOpen(true)}
          />

          <main className="min-w-0">
            <PageHeader
              organization={organization}
              onEdit={() => setEditOpen(true)}
              onAddUser={() => navigate("/dashboard/users")}
            />

            <div className="space-y-5 px-4 py-5 sm:px-6 lg:px-7 lg:py-6">
              <AdminWelcomeStrip
                organization={organization}
                currentUser={currentUser || {}}
              />

              <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
                <MetricCard
                  icon={Users}
                  label="Total members"
                  value={totalUsers}
                  sublabel={`of ${getMaxMembers(organization)}`}
                  trend={{
                    value: `${percent(
                      activeUsers,
                      Math.max(1, totalUsers)
                    )}% active`,
                  }}
                  onClick={() => navigate("/dashboard/users")}
                />

                <MetricCard
                  icon={GraduationCap}
                  label="Students"
                  value={students}
                  sublabel={`${percent(
                    students,
                    Math.max(1, totalUsers)
                  )}% of people`}
                  onClick={() => navigate("/dashboard/students")}
                />

                <MetricCard
                  icon={UserCheck}
                  label="Teachers"
                  value={teachers}
                  sublabel={`${percent(
                    teachers,
                    Math.max(1, totalUsers)
                  )}% of people`}
                  onClick={() => navigate("/dashboard/teachers")}
                />

                <MetricCard
                  icon={BriefcaseBusiness}
                  label="Staff & admin"
                  value={employees + admins + hrUsers}
                  sublabel="Operational team"
                  onClick={() => navigate("/dashboard/employees")}
                />
              </div>

              <div className="grid gap-5 xl:grid-cols-[1.7fr_1fr]">
                <Card className="overflow-hidden">
                  <CardHeader
                    title="Member growth"
                    subtitle="New organization members by month"
                    action={
                      <div className="flex items-center gap-1.5">
                        <TinyButton active>6 months</TinyButton>
                      </div>
                    }
                  />
                  {trend.some((point) => point.value > 0) ? (
                    <TrendChart points={trend} />
                  ) : (
                    <EmptyState
                      icon={Activity}
                      title="Not enough activity yet"
                      text="Member growth will become visible as more people join the organization."
                    />
                  )}
                </Card>

                <Card className="overflow-hidden">
                  <CardHeader
                    title="People mix"
                    subtitle="Distribution by role"
                  />
                  <RoleMixChart
                    counts={roleCounts}
                    total={totalUsers}
                  />
                </Card>
              </div>

              <QuickActions organization={organization} />

              <div className="grid gap-5 xl:grid-cols-[1.25fr_1fr]">
                <Card>
                  <CardHeader
                    title="Department coverage"
                    subtitle="People grouped by department"
                    action={
                      <TinyButton
                        onClick={() => navigate("/dashboard/hr")}
                      >
                        Manage departments
                      </TinyButton>
                    }
                  />
                  <DepartmentChart
                    departments={departmentCounts}
                  />
                </Card>

                <OrganizationHealth
                  organization={organization}
                  totalUsers={totalUsers}
                  activeUsers={activeUsers}
                />
              </div>

              <div className="grid gap-5 xl:grid-cols-[1.25fr_1fr]">
                <RecentPeople
                  users={scopedUsers}
                  onViewAll={() => navigate("/dashboard/users")}
                />
                <ActivityCard users={scopedUsers} />
              </div>

              <PeoplePreview
                users={scopedUsers}
                search={peopleSearch}
                onSearchChange={setPeopleSearch}
                onViewAll={() => navigate("/dashboard/users")}
              />

              <FeatureGrid organization={organization} />

              <div className="grid gap-5 xl:grid-cols-[1.3fr_0.9fr]">
                <OrganizationDetails organization={organization} />
                <ContactCard organization={organization} />
              </div>

              <div className="grid gap-5 xl:grid-cols-3">
                <PlanCard organization={organization} />
                <SecurityCard organization={organization} />
                <OrganizationCodeCard
                  organization={organization}
                />
              </div>

              <PublicIdNotice />

              <div className="flex flex-col gap-3 border-t border-gray-200 pb-5 pt-2 text-[10px] text-gray-400 sm:flex-row sm:items-center sm:justify-between">
                <span>
                  Paisa organization workspace · {organization.name}
                </span>
                <span>
                  Last refreshed{" "}
                  {new Date().toLocaleTimeString("en-IN", {
                    hour: "2-digit",
                    minute: "2-digit",
                  })}
                </span>
              </div>
            </div>
          </main>
        </div>
      </div>

      <MobileMenu
        open={mobileMenu}
        onClose={() => setMobileMenu(false)}
        currentPath={currentPath}
      />

      <EditOrganizationModal
        open={editOpen}
        organization={organization}
        onClose={() => setEditOpen(false)}
        onSaved={() => {
          void organizationsQuery.refetch();
        }}
      />
    </div>
  );
}

// src/pages/dashboard/TeachersPage.tsx

import { useMemo, useState } from 'react'
import {
  Search,
  Plus,
  MoreHorizontal,
  Pencil,
  Trash2,
  GraduationCap,
  Users,
  X,
  Check,
  ChevronDown,
  BookOpen,
  BriefcaseBusiness,
  Mail,
} from 'lucide-react'

import {
  useGetTeachersQuery,
  useCreateTeacherMutation,
} from '@/features/teacher/teachersApi'

import { useGetUsersQuery, rid } from '@/features/users/usersApi'
import { useAppSelector } from '@/app/store'

import PageHeader from '@/components/ui/PageHeader'
import Button from '@/components/ui/button'
import Badge from '@/components/ui/badge'
import Modal from '@/components/ui/Modal'
import {
  LoadingGrid,
  ErrorState,
  EmptyState,
} from '@/components/ui/StateViews'

type Teacher = {
  _id: string
  userId:
    | {
        _id: string
        name: string
        email: string
        userCode?: string
      }
    | string
    | null
  instituteId:
    | {
        _id: string
        name: string
        type?: string
      }
    | string
    | null
  subject?: string
  qualifications?: string
  experience?: number | string
  createdAt?: string
}

export default function TeachersPage() {
  const authUser = useAppSelector((s) => s.auth.user)

  const canManage = [
    'super_admin',
    'admin',
    'principal',
    'hr',
  ].includes(authUser?.role ?? '')

  const {
    data: teachers = [],
    isLoading,
    isError,
    refetch,
  } = useGetTeachersQuery()

  const { data: users = [] } = useGetUsersQuery()

  const [createTeacher, { isLoading: createPending }] =
    useCreateTeacherMutation()

  const [search, setSearch] = useState('')
  const [subjectFilter, setSubjectFilter] = useState('all')
  const [showCreate, setShowCreate] = useState(false)
  const [menuId, setMenuId] = useState<string | null>(null)
  const [error, setError] = useState('')

  const [form, setForm] = useState({
    userId: '',
    subject: '',
    qualifications: '',
    experience: '',
  })

  const availableTeachers = useMemo(() => {
    const linkedUserIds = new Set(
      teachers.map((teacher: Teacher) =>
        typeof teacher.userId === 'object' && teacher.userId
          ? teacher.userId._id
          : teacher.userId,
      ),
    )

    return users.filter(
      (user: any) =>
        user.role === 'teacher' &&
        !linkedUserIds.has(user._id) &&
        !linkedUserIds.has(user.publicId),
    )
  }, [users, teachers])

  const subjects = useMemo(() => {
    const values = teachers
      .map((teacher: Teacher) => teacher.subject?.trim())
      .filter(Boolean) as string[]

    return [...new Set(values)].sort()
  }, [teachers])

  const filteredTeachers = useMemo(() => {
    const query = search.trim().toLowerCase()

    return teachers.filter((teacher: Teacher) => {
      const person =
        typeof teacher.userId === 'object' && teacher.userId
          ? teacher.userId
          : null

      const matchesSearch =
        !query ||
        person?.name?.toLowerCase().includes(query) ||
        person?.email?.toLowerCase().includes(query) ||
        person?.userCode?.toLowerCase().includes(query) ||
        teacher.subject?.toLowerCase().includes(query) ||
        teacher.qualifications?.toLowerCase().includes(query)

      const matchesSubject =
        subjectFilter === 'all' ||
        teacher.subject === subjectFilter

      return matchesSearch && matchesSubject
    })
  }, [teachers, search, subjectFilter])

  const resetForm = () => {
    setForm({
      userId: '',
      subject: '',
      qualifications: '',
      experience: '',
    })

    setError('')
  }

  const openCreate = () => {
    resetForm()
    setShowCreate(true)
  }

  const closeCreate = () => {
    if (createPending) return

    setShowCreate(false)
    resetForm()
  }

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!form.userId) {
      setError('Select a teacher')
      return
    }

    setError('')

    try {
      await createTeacher({
        userId: form.userId,
        subject: form.subject.trim() || undefined,
        qualifications:
          form.qualifications.trim() || undefined,
        experience:
          form.experience.trim()
            ? Number(form.experience)
            : undefined,
      }).unwrap()

      closeCreate()
    } catch (e) {
      const err = e as { data?: { message?: string }; error?: { data?: { message?: string } } }
      setError(
        err?.data?.message ??
          err?.error?.data?.message ??
          'Failed to create teacher profile',
      )
    }
  }

  const totalExperience = useMemo(() => {
    const values = teachers
      .map((teacher: Teacher) =>
        Number(teacher.experience ?? 0),
      )
      .filter((value: number) => !Number.isNaN(value))

    if (!values.length) return 0

    return Math.round(
      values.reduce((a: number, b: number) => a + b, 0),
    )
  }, [teachers])

  return (
    <div className="min-h-screen bg-[#f6f6f7]">
      <div className="mx-auto max-w-[1500px] px-6 py-7 lg:px-8">
        <PageHeader
          title="Teachers"
          subtitle="Manage teaching staff, subjects and professional profiles"
          actions={
            canManage ? (
              <Button onClick={openCreate}>
                <Plus size={16} />
                Add teacher
              </Button>
            ) : undefined
          }
        />

        {/* STATS */}
        <div className="mt-7 grid grid-cols-1 gap-4 md:grid-cols-3">
          <StatCard
            icon={<GraduationCap size={18} />}
            label="Total teachers"
            value={teachers.length}
            description="Teaching staff"
          />

          <StatCard
            icon={<BookOpen size={18} />}
            label="Subjects"
            value={subjects.length}
            description="Currently assigned"
          />

          <StatCard
            icon={<BriefcaseBusiness size={18} />}
            label="Experience"
            value={`${totalExperience} yrs`}
            description="Combined experience"
          />
        </div>

        {/* TOOLBAR */}
        <div className="mt-7 rounded-2xl border border-gray-200 bg-white shadow-sm">
          <div className="flex flex-col gap-4 p-4 lg:flex-row lg:items-center lg:justify-between">
            <div className="relative w-full lg:max-w-xl">
              <Search
                size={17}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />

              <input
                value={search}
                onChange={(e) =>
                  setSearch(e.target.value)
                }
                placeholder="Search teachers, email, ID or subject..."
                className="h-10 w-full rounded-xl border border-gray-200 bg-gray-50 pl-10 pr-10 text-sm outline-none transition placeholder:text-gray-400 focus:border-gray-400 focus:bg-white"
              />

              {search && (
                <button
                  onClick={() => setSearch('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-900"
                >
                  <X size={15} />
                </button>
              )}
            </div>

            <div className="flex items-center gap-2">
              <div className="relative">
                <select
                  value={subjectFilter}
                  onChange={(e) =>
                    setSubjectFilter(e.target.value)
                  }
                  className="h-10 appearance-none rounded-xl border border-gray-200 bg-white px-3 pr-9 text-sm outline-none focus:border-gray-400"
                >
                  <option value="all">
                    All subjects
                  </option>

                  {subjects.map((subject) => (
                    <option
                      key={subject}
                      value={subject}
                    >
                      {subject}
                    </option>
                  ))}
                </select>

                <ChevronDown
                  size={15}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                />
              </div>

              {canManage && (
                <Button onClick={openCreate}>
                  <Plus size={15} />
                  Add
                </Button>
              )}
            </div>
          </div>

          <div className="border-t border-gray-100 px-4 py-3">
            <div className="flex items-center justify-between text-xs text-gray-500">
              <span>
                {filteredTeachers.length}{' '}
                {filteredTeachers.length === 1
                  ? 'teacher'
                  : 'teachers'}
              </span>

              {(search ||
                subjectFilter !== 'all') && (
                <button
                  onClick={() => {
                    setSearch('')
                    setSubjectFilter('all')
                  }}
                  className="font-medium text-gray-900 hover:underline"
                >
                  Clear filters
                </button>
              )}
            </div>
          </div>
        </div>

        {/* CONTENT */}
        <div className="mt-4">
          {isLoading ? (
            <LoadingGrid />
          ) : isError ? (
            <ErrorState
              onRetry={() => refetch()}
            />
          ) : !filteredTeachers.length ? (
            <div className="rounded-2xl border border-gray-200 bg-white py-20">
              <EmptyState
                icon={
                  <GraduationCap size={44} />
                }
                title={
                  search || subjectFilter !== 'all'
                    ? 'No teachers found'
                    : 'No teacher profiles yet'
                }
                hint={
                  search || subjectFilter !== 'all'
                    ? 'Try changing your search or filters'
                    : canManage
                      ? 'Create a teacher profile for one of your teacher accounts'
                      : 'Teacher profiles will appear here'
                }
                action={
                  canManage &&
                  !search &&
                  subjectFilter === 'all' ? (
                    <Button onClick={openCreate}>
                      <Plus size={16} />
                      Add teacher
                    </Button>
                  ) : undefined
                }
              />
            </div>
          ) : (
            <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm">
              {/* HEADER */}
              <div className="hidden grid-cols-[minmax(300px,2fr)_180px_minmax(180px,1fr)_130px_60px] border-b border-gray-100 bg-gray-50/70 px-5 py-3 text-[11px] font-semibold uppercase tracking-wide text-gray-400 md:grid">
                <span>Teacher</span>
                <span>Subject</span>
                <span>Qualifications</span>
                <span>Experience</span>
                <span />
              </div>

              <div className="divide-y divide-gray-100">
                {filteredTeachers.map(
                  (teacher: Teacher) => {
                    const person =
                      typeof teacher.userId ===
                        'object' &&
                      teacher.userId
                        ? teacher.userId
                        : null

                    const id =
                      teacher._id

                    const initials =
                      person?.name
                        ?.split(' ')
                        .map(
                          (part) =>
