                  required
                  className="form-input appearance-none pr-10"
                >
                  <option value="">
                    Select teacher
                  </option>

                  {availableTeachers.map(
                    (teacher: any) => (
                      <option
                        key={rid(teacher)}
                        value={rid(
                          teacher,
                        )}
                      >
                        {teacher.name} —{' '}
                        {teacher.email}
                      </option>
                    ),
                  )}
                </select>

                <ChevronDown
                  size={15}
                  className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                />
              </div>

              {!availableTeachers.length && (
                <p className="mt-2 text-xs text-amber-600">
                  No unlinked teacher accounts are
                  available.
                </p>
              )}
            </FormField>

            {/* SUBJECT */}
            <FormField label="Primary subject">
              <input
                value={form.subject}
                onChange={(e) =>
                  setForm((prev) => ({
                    ...prev,
                    subject:
                      e.target.value,
                  }))
                }
                placeholder="e.g. Mathematics"
                className="form-input"
              />
            </FormField>

            {/* QUALIFICATION */}
            <FormField label="Qualifications">
              <input
                value={
                  form.qualifications
                }
                onChange={(e) =>
                  setForm((prev) => ({
                    ...prev,
                    qualifications:
                      e.target.value,
                  }))
                }
                placeholder="e.g. M.Sc Mathematics, B.Ed"
                className="form-input"
              />
            </FormField>

            {/* EXPERIENCE */}
            <FormField label="Experience">
              <div className="relative">
                <input
                  type="number"
                  min="0"
                  value={
                    form.experience
                  }
                  onChange={(e) =>
                    setForm((prev) => ({
                      ...prev,
                      experience:
                        e.target.value,
                    }))
                  }
                  placeholder="e.g. 5"
                  className="form-input pr-16"
                />

                <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-xs text-gray-400">
                  years
                </span>
              </div>
            </FormField>

            {error && (
              <div className="rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm text-red-600">
                {error}
              </div>
            )}

            <div className="flex items-center justify-between border-t border-gray-100 pt-5">
              <button
                type="button"
                onClick={closeCreate}
                className="rounded-xl px-4 py-2.5 text-sm font-medium text-gray-500 transition hover:bg-gray-100 hover:text-gray-900"
              >
                Cancel
              </button>

              <Button
                type="submit"
                loading={createPending}
              >
                <Check size={16} />
                Create teacher
              </Button>
            </div>
          </form>
        </Modal>
      </div>

      <style>{`
        .form-input {
          width: 100%;
          border-radius: 0.75rem;
          border: 1px solid rgb(229 231 235);
          background: white;
          padding: 0.65rem 0.8rem;
          font-size: 0.875rem;
          color: rgb(17 24 39);
          outline: none;
          transition: all 150ms ease;
        }

        .form-input::placeholder {
          color: rgb(156 163 175);
        }

        .form-input:focus {
          border-color: rgb(17 24 39);
          box-shadow: 0 0 0 3px rgb(17 24 39 / 0.05);
        }
      `}</style>
    </div>
  )
}

function StatCard({
  icon,
  label,
  value,
  description,
}: {
  icon: React.ReactNode
  label: string
  value: React.ReactNode
  description: string
}) {
  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-xs font-medium text-gray-500">
            {label}
          </p>

          <p className="mt-2 text-2xl font-semibold tracking-tight text-gray-900">
            {value}
          </p>

          <p className="mt-1 text-xs text-gray-400">
            {description}
          </p>
        </div>

        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-gray-100 text-gray-600">
          {icon}
        </div>
      </div>
    </div>
  )
}

function FormField({
  label,
  required,
  children,
}: {
  label: string
  required?: boolean
  children: React.ReactNode
}) {
  return (
    <div>
      <label className="mb-1.5 block text-xs font-semibold text-gray-700">
        {label}
        {required && (
          <span className="ml-1 text-red-500">
            *
          </span>
        )}
      </label>

      {children}
    </div>
  )
}

// pages/dashboard/UserDetailPage.tsx

import {
  ArrowLeft,
  BriefcaseBusiness,
  CalendarDays,
  Check,
  Clipboard,
  Copy,
  Edit3,
  GraduationCap,
  KeyRound,
  Lock,
  Mail,
  MapPin,
  MoreHorizontal,
  Phone,
  Save,
  Shield,
  User,
  UserCheck,
  UserRound,
  X,
} from 'lucide-react'

import {
  useMemo,
  useState,
} from 'react'

import {
  useNavigate,
  useParams,
} from 'react-router-dom'

import {
  useGetUserByIdQuery,
  useUpdateUserMutation,
  useGetUsersQuery
} from '@/features/users/usersApi'
import { useGetDepartmentsQuery } from '@/features/departments/departmentsApi'

import type {
  UpdateUserPayload,
} from '@/features/users/usersApi'

type Tab =
  | 'overview'
  | 'profile'
  | 'employment'
  | 'academic'
  | 'security'

const EMPTY = 'Not provided'

const formatDate = (
  value?: string | null
) => {
  if (!value) return EMPTY

  const date = new Date(value)

  if (Number.isNaN(date.getTime())) {
    return value
  }

  return date.toLocaleDateString(
    'en-IN',
    {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    }
  )
}

const formatDateTime = (
  value?: string | null
) => {
  if (!value) return EMPTY

  const date = new Date(value)

  if (Number.isNaN(date.getTime())) {
    return value
  }

  return date.toLocaleString(
    'en-IN',
    {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    }
  )
}

const roleLabel = (role?: string) => {
  if (!role) return 'User'

  return role
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (c) =>
      c.toUpperCase()
    )
}

const getInitials = (
  name?: string | null
) => {
  if (!name) return 'U'

  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((x) => x[0])
    .join('')
    .toUpperCase()
}

const Field = ({
  label,
  value,
  mono = false,
}: {
  label: string
  value?: React.ReactNode
  mono?: boolean
}) => (
  <div className="rounded-xl border border-slate-100 bg-white p-4">
    <p className="text-xs font-medium uppercase tracking-wide text-slate-400">
      {label}
    </p>

    <div
      className={`mt-1 text-sm font-medium text-slate-900 ${
        mono ? 'font-mono' : ''
      }`}
    >
      {value ?? '—'}
    </div>
  </div>
)

const Section = ({
  icon: Icon,
  title,
  description,
  children,
  action,
}: {
  icon: React.ElementType
  title: string
  description?: string
  children: React.ReactNode
  action?: React.ReactNode
}) => (
  <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
    <div className="flex items-center justify-between border-b border-slate-100 px-6 py-5">
      <div className="flex items-center gap-3">
        <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-slate-100">
          <Icon
            size={18}
            className="text-slate-700"
          />
        </div>

        <div>
          <h2 className="text-sm font-bold text-slate-950">
            {title}
          </h2>

          {description && (
            <p className="mt-0.5 text-xs text-slate-500">
              {description}
            </p>
          )}
        </div>
      </div>

      {action}
    </div>

    <div className="p-6">
      {children}
    </div>
  </section>
)

const StatusBadge = ({
  status,
}: {
  status?: string
}) => {
  const active = status === 'active'

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold ${
        active
          ? 'bg-emerald-50 text-emerald-700'
          : 'bg-slate-100 text-slate-600'
      }`}
    >
      <span
        className={`h-1.5 w-1.5 rounded-full ${
          active
            ? 'bg-emerald-500'
            : 'bg-slate-400'
        }`}
      />

      {status
        ? status.charAt(0).toUpperCase() +
          status.slice(1)
        : 'Unknown'}
    </span>
  )
}

export default function UserDetailPage() {
  const navigate = useNavigate()

  const { publicId } = useParams<{
    publicId: string
  }>()

  const id = publicId ?? ''

  const {
    data: user,
    isLoading,
    isFetching,
    isError,
    error,
    refetch,
  } = useGetUserByIdQuery(id, {
    skip: !id,
  })
const { data: users = [] } = useGetUsersQuery({
  instituteId:
    typeof user?.instituteId === 'string'
      ? user.instituteId
      : user?.instituteId?._id,
})

const managers = users.filter((manager) => {
  const managerInstituteId =
    typeof manager.instituteId === 'object' &&
    manager.instituteId !== null
      ? manager.instituteId._id
      : manager.instituteId

  const userInstituteId =
    typeof user?.instituteId === 'object' &&
    user.instituteId !== null
      ? user.instituteId._id
      : user?.instituteId

  return (
    manager._id !== user?._id &&
    managerInstituteId &&
    userInstituteId &&
    managerInstituteId === userInstituteId &&
    ['super_admin', 'admin', 'principal', 'hr'].includes(
      manager.role
    )
  )
})

const { data: departments = [] } =
  useGetDepartmentsQuery()
  const [updateUser, updateState] =
    useUpdateUserMutation()

  const [activeTab, setActiveTab] =
    useState<Tab>('overview')

  const [editing, setEditing] =
    useState(false)

  const [copied, setCopied] =
    useState(false)

  const [menuOpen, setMenuOpen] =
    useState(false)

const [form, setForm] = useState({
  name: '',
  displayName: '',
  email: '',
  status: 'active' as 'active' | 'inactive',

  phone: '',
  alternatePhone: '',
  address: '',
  city: '',
  state: '',
  country: '',
  pincode: '',

  department: '',
  designation: '',
  reportingManager: '',
  workLocation: '',
  workEmail: '',
  dateOfJoining: '',
  probationEndDate: '',
  skills: '',

  rollNumber: '',
  grade: '',
  section: '',
  guardianName: '',
  guardianPhone: '',
  admissionDate: '',
})
    
// Re-initialize the form from the loaded user during render (avoids a
// cascading setState inside an effect). Guarded by the previous user.
const [prevUser, setPrevUser] = useState(user)
if (user && user !== prevUser) {
  setPrevUser(user)

  const department =
    typeof user.employment?.department === 'object' &&
    user.employment.department !== null
      ? user.employment.department._id
      : user.employment?.department ?? ''

  setForm({
    name: user.name ?? '',
    displayName: user.displayName ?? '',
    email: user.email ?? '',
    status: user.status === 'inactive' ? 'inactive' : 'active',

    phone: user.profile?.phone ?? '',
    alternatePhone: user.profile?.alternatePhone ?? '',
    address: user.profile?.address ?? '',
    city: user.profile?.city ?? '',
    state: user.profile?.state ?? '',
    country: user.profile?.country ?? '',
    pincode: user.profile?.pincode ?? '',

    department,

    designation: user.employment?.designation ?? '',

    reportingManager:
      typeof user.employment?.reportingManager === 'object' &&
      user.employment.reportingManager !== null
        ? user.employment.reportingManager._id
        : user.employment?.reportingManager ?? '',

    workLocation: user.employment?.workLocation ?? '',
    workEmail: user.employment?.workEmail ?? '',

    dateOfJoining: user.employment?.dateOfJoining
      ? user.employment.dateOfJoining.slice(0, 10)
      : '',

    probationEndDate: user.employment?.probationEndDate
      ? user.employment.probationEndDate.slice(0, 10)
      : '',

    skills: user.employment?.skills?.join(', ') ?? '',

    rollNumber: user.academic?.rollNumber ?? '',
    grade: user.academic?.grade ?? '',
    section: user.academic?.section ?? '',
    guardianName: user.academic?.guardianName ?? '',
    guardianPhone: user.academic?.guardianPhone ?? '',

    admissionDate: user.academic?.admissionDate
      ? user.academic.admissionDate.slice(0, 10)
      : '',
  })
}

  const initials = useMemo(
    () => getInitials(user?.displayName || user?.name),
    [user]
  )

 const saveChanges = async () => {
  if (!user || !form) return

  try {
    const payload: UpdateUserPayload = {
      name: form.name,
      displayName: form.displayName || undefined,
      status: form.status,

      profile: {
        phone: form.phone || undefined,
        alternatePhone: form.alternatePhone || undefined,
        address: form.address || undefined,
        city: form.city || undefined,
        state: form.state || undefined,
        country: form.country || undefined,
        pincode: form.pincode || undefined,
      },

      employment: {
        department: form.department || undefined,
        designation: form.designation || undefined,
        reportingManager: form.reportingManager || undefined,
        workLocation: form.workLocation || undefined,
        workEmail: form.workEmail || undefined,
        dateOfJoining: form.dateOfJoining || undefined,
        probationEndDate: form.probationEndDate || undefined,
        skills: form.skills
          ? form.skills
              .split(',')
              .map((x: string) => x.trim())
              .filter(Boolean)
          : [],
      },

      academic: {
        rollNumber: form.rollNumber || undefined,
        grade: form.grade || undefined,
        section: form.section || undefined,
        guardianName: form.guardianName || undefined,
        guardianPhone: form.guardianPhone || undefined,
        admissionDate: form.admissionDate || undefined,
      },
    }

    if (
      typeof form.email === 'string' &&
      form.email.trim() !== '' &&
      form.email.trim() !== user.email
    ) {
      payload.email = form.email.trim()
    }

    await updateUser({
      id,
      payload,
    }).unwrap()

    setEditing(false)

    await refetch()
  } catch (error) {
    console.error('Unable to update user:', error)
  }
}

  const copyPublicId = async () => {
    if (!user?.publicId) return

    await navigator.clipboard.writeText(
      user.publicId
    )

    setCopied(true)

    window.setTimeout(() => {
      setCopied(false)
    }, 1600)
  }

  const updateField = (
    field: string,
    value: string
  ) => {
    setForm((previous: any) => ({
      ...previous,
      [field]: value,
    }))
  }

  const deactivate = async () => {
    if (!user) return

    if (
      !window.confirm(
        `Deactivate ${user.name}?`
      )
    ) {
      return
    }

    try {
      await updateUser({
        id,
        payload: {
          status: 'inactive',
        },
      }).unwrap()

      setMenuOpen(false)

      await refetch()
    } catch {
      // RTK Query state handles the error
    }
  }

  if (isLoading) {
    return (
      <div className="min-h-[70vh] bg-slate-50 p-6">
        <div className="mx-auto max-w-[1500px] animate-pulse space-y-6">
          <div className="h-10 w-40 rounded-lg bg-slate-200" />

          <div className="h-48 rounded-2xl bg-slate-200" />

          <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_340px]">
            <div className="h-[500px] rounded-2xl bg-slate-200" />

            <div className="h-[300px] rounded-2xl bg-slate-200" />
          </div>
        </div>
      </div>
    )
  }

  if (isError || !user) {
    return (
      <div className="min-h-[70vh] bg-slate-50 p-6">
        <div className="mx-auto max-w-2xl rounded-2xl border border-red-200 bg-white p-8 text-center shadow-sm">
          <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-red-50">
            <X className="text-red-600" />
          </div>

          <h2 className="text-lg font-bold text-slate-950">
            Unable to load user
          </h2>

          <p className="mt-2 text-sm text-slate-500">
            {(error as any)?.data?.message ||
              'The requested user could not be found.'}
          </p>

          <div className="mt-6 flex justify-center gap-3">
            <button
              onClick={() => navigate(-1)}
              className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold"
            >
              Go back
            </button>

            <button
              onClick={() => refetch()}
              className="rounded-xl bg-slate-950 px-4 py-2 text-sm font-semibold text-white"
            >
              Retry
            </button>
          </div>
        </div>
      </div>
    )
  }

  const isSaving =
    updateState.isLoading

  return (
    <div className="min-h-screen bg-slate-50">
      <div className="mx-auto max-w-[1500px] px-4 py-6 sm:px-6 lg:px-8">
        <div className="mb-5 flex items-center justify-between">
          <button
            onClick={() => navigate(-1)}
            className="inline-flex items-center gap-2 rounded-xl px-2 py-2 text-sm font-semibold text-slate-600 transition hover:bg-white hover:text-slate-950"
          >
            <ArrowLeft size={17} />
            Users
          </button>

          <div className="flex items-center gap-2">
            {isFetching && (
              <span className="mr-2 text-xs text-slate-400">
                Refreshing...
              </span>
            )}

            {!editing ? (
              <>
                <button
                  onClick={() =>
                    setEditing(true)
                  }
                  className="inline-flex items-center gap-2 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-slate-800"
                >
                  <Edit3 size={16} />
                  Edit user
                </button>

                <div className="relative">
                  <button
                    onClick={() =>
                      setMenuOpen((x) => !x)
                    }
                    className="rounded-xl border border-slate-200 bg-white p-2.5 text-slate-600 shadow-sm hover:bg-slate-50"
                  >
                    <MoreHorizontal size={18} />
                  </button>

