                    <Field
                      label="Phone"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.phone ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'phone',
                                e.target
                                  .value
                              )
                            }
                            className="w-full border-0 bg-transparent p-0 text-sm font-medium outline-none"
                          />
                        ) : (
                          user.profile
                            ?.phone
                        )
                      }
                    />

                    <Field
                      label="City"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.city ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'city',
                                e.target
                                  .value
                              )
                            }
                            className="w-full border-0 bg-transparent p-0 text-sm font-medium outline-none"
                          />
                        ) : (
                          user.profile
                            ?.city
                        )
                      }
                    />

                    <Field
                      label="State"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.state ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'state',
                                e.target
                                  .value
                              )
                            }
                            className="w-full border-0 bg-transparent p-0 text-sm font-medium outline-none"
                          />
                        ) : (
                          user.profile
                            ?.state
                        )
                      }
                    />

                    <Field
                      label="Country"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.country ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'country',
                                e.target
                                  .value
                              )
                            }
                            className="w-full border-0 bg-transparent p-0 text-sm font-medium outline-none"
                          />
                        ) : (
                          user.profile
                            ?.country
                        )
                      }
                    />

                    <Field
                      label="Pincode"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.pincode ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'pincode',
                                e.target
                                  .value
                              )
                            }
                            className="w-full border-0 bg-transparent p-0 text-sm font-medium outline-none"
                          />
                        ) : (
                          user.profile
                            ?.pincode
