                          value={
                            form?.designation ??
                            ''
                          }
                          onChange={(e) =>
                            updateField(
                              'designation',
                              e.target
                                .value
                            )
                          }
                          className="w-full outline-none"
                        />
                      ) : (
                        user.employment
                          ?.designation
                      )
                    }
                  />

<Field
  label="Reporting manager"
  value={
    editing ? (
      <select
        value={form?.reportingManager ?? ''}
        onChange={(e) =>
          updateField('reportingManager', e.target.value)
        }
        className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-normal outline-none transition focus:border-slate-400 focus:ring-2 focus:ring-slate-100"
      >
        <option value="">Select reporting manager</option>

        {managers
          .filter(
            (manager: any) =>
              manager._id !== user._id &&
              ['super_admin', 'admin', 'principal', 'hr'].includes(
                manager.role
              )
          )
          .map((manager: any) => (
            <option key={manager._id} value={manager.publicId}>
              {manager.name} — {manager.role}
            </option>
          ))}
      </select>
    ) : typeof user.employment?.reportingManager === 'object' &&
      user.employment.reportingManager !== null ? (
      user.employment.reportingManager.name
    ) : (
      user.employment?.reportingManager || 'Not assigned'
    )
  }
/>
                  <Field
                    label="Work location"
                    value={
                      editing ? (
                        <input
                          value={
                            form?.workLocation ??
                            ''
                          }
                          onChange={(e) =>
                            updateField(
                              'workLocation',
                              e.target
                                .value
                            )
                          }
                          className="w-full outline-none"
                        />
                      ) : (
                        user.employment
                          ?.workLocation
                      )
                    }
                  />

                  <Field
                    label="Work email"
                    value={
                      editing ? (
                        <input
                          value={
                            form?.workEmail ??
                            ''
                          }
                          onChange={(e) =>
                            updateField(
                              'workEmail',
                              e.target
                                .value
                            )
                          }
                          className="w-full outline-none"
                        />
                      ) : (
                        user.employment
                          ?.workEmail
                      )
                    }
                  />

                  <Field
                    label="Joining date"
                    value={
                      editing ? (
                        <input
                          type="date"
                          value={
                            form?.dateOfJoining ??
                            ''
                          }
                          onChange={(e) =>
                            updateField(
                              'dateOfJoining',
                              e.target
                                .value
                            )
                          }
                          className="w-full outline-none"
                        />
                      ) : (
                        formatDate(
                          user.employment
                            ?.dateOfJoining
                        )
                      )
                    }
                  />

                  <Field
                    label="Probation end date"
                    value={
                      editing ? (
                        <input
                          type="date"
                          value={
                            form?.probationEndDate ??
                            ''
                          }
                          onChange={(e) =>
                            updateField(
                              'probationEndDate',
                              e.target
                                .value
                            )
                          }
                          className="w-full outline-none"
                        />
                      ) : (
                        formatDate(
                          user.employment
                            ?.probationEndDate
                        )
                      )
                    }
                  />

                  <Field
                    label="Skills"
                    value={
                      editing ? (
                        <input
                          value={
                            form?.skills ??
                            ''
                          }
                          onChange={(e) =>
                            updateField(
                              'skills',
                              e.target
                                .value
                            )
                          }
                          className="w-full outline-none"
                        />
                      ) : (
                        user.employment
                          ?.skills
                          ?.join(', ')
                      )
                    }
                  />
                </div>
              </Section>
            )}

            {activeTab ===
              'academic' && (
              <Section
                icon={GraduationCap}
                title="Academic information"
                description="Academic identity and student-specific information"
              >
                {user.role !==
                'student' ? (
                  <div className="rounded-xl border border-slate-200 bg-slate-50 p-5 text-sm text-slate-500">
                    Academic information is
                    not applicable to this
                    role.
                  </div>
                ) : (
                  <div className="grid gap-4 sm:grid-cols-2">
                    <Field
                      label="Enrollment number"
                      value={
                        user.userCode
                      }
                      mono
                    />

                    <Field
                      label="Roll number"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.rollNumber ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'rollNumber',
                                e.target
                                  .value
                              )
                            }
                            className="w-full outline-none"
                          />
                        ) : (
                          user.academic
                            ?.rollNumber
                        )
                      }
                    />

                    <Field
                      label="Grade"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.grade ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'grade',
                                e.target
                                  .value
                              )
                            }
                            className="w-full outline-none"
                          />
                        ) : (
                          user.academic
                            ?.grade
                        )
                      }
                    />

                    <Field
                      label="Section"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.section ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'section',
                                e.target
                                  .value
                              )
                            }
                            className="w-full outline-none"
                          />
                        ) : (
                          user.academic
                            ?.section
                        )
                      }
                    />

                    <Field
                      label="Guardian name"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.guardianName ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'guardianName',
                                e.target
                                  .value
                              )
                            }
                            className="w-full outline-none"
                          />
                        ) : (
                          user.academic
                            ?.guardianName
                        )
                      }
                    />

                    <Field
                      label="Guardian phone"
                      value={
                        editing ? (
                          <input
                            value={
                              form?.guardianPhone ??
                              ''
                            }
                            onChange={(e) =>
                              updateField(
                                'guardianPhone',
                                e.target
                                  .value
                              )
                            }
                            className="w-full outline-none"
                            
                          />
                        ) : (
                          user.academic
                            ?.guardianPhone
                        )
                      }
                    />

                    <Field
                      label="Admission date"
                      value={formatDate(
                        user.academic
                          ?.admissionDate
                      )}
                    />
                  </div>
                )}
              </Section>
            )}

            {activeTab ===
              'security' && (
              <>
                <Section
                  icon={Shield}
                  title="Account security"
                  description="Authentication and account controls"
                >
                  <div className="grid gap-4 sm:grid-cols-3">
                    <Field
                      label="Email verification"
                      value={
                        user.emailVerified
                          ? 'Verified'
                          : 'Not verified'
                      }
                    />

                    <Field
                      label="Two-factor authentication"
                      value={
                        user.twoFactorEnabled
                          ? 'Enabled'
                          : 'Disabled'
                      }
                    />

                    <Field
                      label="Password status"
                      value={
                        user.mustChangePassword
                          ? 'Change required'
                          : 'Normal'
                      }
                    />

                    <Field
                      label="Failed login attempts"
                      value={
                        user.failedAttempts ??
                        0
                      }
                    />

                    <Field
                      label="Locked until"
                      value={formatDateTime(
                        user.lockedUntil
                      )}
                    />

                    <Field
                      label="Last active"
                      value={formatDateTime(
                        user.lastActiveAt
                      )}
                    />
                  </div>
                </Section>

                <Section
                  icon={KeyRound}
                  title="Authentication"
                  description="Recent authentication information"
                >
                  <div className="space-y-3">
                    <div className="flex items-center justify-between rounded-xl border border-slate-200 p-4">
                      <div className="flex items-center gap-3">
                        <Mail
                          size={17}
                          className="text-slate-400"
                        />

                        <div>
                          <p className="text-sm font-semibold text-slate-900">
                            Email verification
                          </p>

                          <p className="text-xs text-slate-500">
                            {user.emailVerifiedAt
                              ? `Verified ${formatDateTime(
                                  user.emailVerifiedAt
                                )}`
                              : 'Email has not been verified'}
                          </p>
                        </div>
                      </div>

                      <span
                        className={`rounded-full px-2.5 py-1 text-xs font-semibold ${
                          user.emailVerified
                            ? 'bg-emerald-50 text-emerald-700'
                            : 'bg-amber-50 text-amber-700'
                        }`}
                      >
                        {user.emailVerified
                          ? 'Verified'
                          : 'Pending'}
                      </span>
                    </div>

                    <div className="flex items-center justify-between rounded-xl border border-slate-200 p-4">
                      <div className="flex items-center gap-3">
                        <Lock
                          size={17}
                          className="text-slate-400"
                        />

                        <div>
                          <p className="text-sm font-semibold text-slate-900">
                            Password
                          </p>

                          <p className="text-xs text-slate-500">
                            {user.passwordChangedAt
                              ? `Last changed ${formatDateTime(
                                  user.passwordChangedAt
                                )}`
                              : 'Password has not been changed'}
                          </p>
                        </div>
                      </div>

                      <span className="text-xs font-semibold text-slate-500">
                        Protected
                      </span>
                    </div>
                  </div>
                </Section>
              </>
            )}
          </div>

          <aside className="space-y-5">
            <Section
              icon={Clipboard}
              title="User summary"
            >
              <div className="-mx-6 -my-6 divide-y divide-slate-100">
                <div className="flex items-center gap-3 px-6 py-4">
                  <Mail
                    size={16}
                    className="text-slate-400"
                  />

                  <div className="min-w-0">
                    <p className="text-[11px] text-slate-400">
                      Email
                    </p>

                    <p className="truncate text-sm font-medium text-slate-900">
                      {user.email ||
                        EMPTY}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3 px-6 py-4">
                  <Phone
                    size={16}
                    className="text-slate-400"
                  />

                  <div>
                    <p className="text-[11px] text-slate-400">
                      Phone
                    </p>

                    <p className="text-sm font-medium text-slate-900">
                      {user.profile
                        ?.phone ||
                        EMPTY}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3 px-6 py-4">
                  <MapPin
                    size={16}
                    className="text-slate-400"
                  />

                  <div>
                    <p className="text-[11px] text-slate-400">
                      Location
                    </p>

                    <p className="text-sm font-medium text-slate-900">
                      {[
                        user.profile
                          ?.city,
                        user.profile
                          ?.state,
                        user.profile
                          ?.country,
                      ]
                        .filter(Boolean)
                        .join(', ') ||
                        EMPTY}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3 px-6 py-4">
                  <CalendarDays
                    size={16}
                    className="text-slate-400"
                  />

                  <div>
                    <p className="text-[11px] text-slate-400">
                      Created
                    </p>

                    <p className="text-sm font-medium text-slate-900">
                      {formatDate(
                        user.createdAt
                      )}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3 px-6 py-4">
                  <UserCheck
                    size={16}
                    className="text-slate-400"
                  />

                  <div>
                    <p className="text-[11px] text-slate-400">
                      Last login
                    </p>

                    <p className="text-sm font-medium text-slate-900">
                      {formatDateTime(
                        user.lastLogin
                      )}
                    </p>
                  </div>
                </div>
              </div>
            </Section>

            <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
              <div className="mb-3 flex items-center justify-between">
                <div>
                  <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400">
                    Public ID
                  </p>

                  <p className="mt-1 text-xs text-slate-500">
                    System identity
                  </p>
                </div>

                <button
                  onClick={copyPublicId}
                  disabled={!user.publicId}
                  className="rounded-lg border border-slate-200 p-2 text-slate-500 hover:bg-slate-50"
                >
                  {copied ? (
                    <Check
                      size={15}
                      className="text-emerald-600"
                    />
                  ) : (
                    <Copy size={15} />
                  )}
                </button>
              </div>

              <div className="rounded-xl bg-slate-50 px-3 py-3 font-mono text-xs text-slate-600">
                {user.publicId ||
                  user._id}
              </div>
            </div>

            <Section
              icon={Shield}
              title="Account access"
              description="Current authentication state"
            >
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-slate-500">
                    Account
                  </span>

                  <StatusBadge
                    status={
                      user.status
                    }
                  />
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-sm text-slate-500">
                    Email
                  </span>

                  <span className="text-xs font-semibold text-slate-700">
                    {user.emailVerified
                      ? 'Verified'
                      : 'Pending'}
                  </span>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-sm text-slate-500">
                    2FA
                  </span>

                  <span className="text-xs font-semibold text-slate-700">
                    {user.twoFactorEnabled
                      ? 'Enabled'
                      : 'Disabled'}
                  </span>
                </div>
              </div>
            </Section>

            {user.role ===
              'student' && (
              <Section
                icon={GraduationCap}
                title="Student"
                description="Academic identity"
              >
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-slate-500">
                      Enrollment
                    </span>

                    <span className="font-mono text-xs font-semibold text-slate-900">
                      {user.userCode ||
                        EMPTY}
                    </span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-sm text-slate-500">
                      Roll number
                    </span>

                    <span className="text-sm font-semibold text-slate-900">
                      {user.academic
                        ?.rollNumber ||
                        EMPTY}
                    </span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-sm text-slate-500">
                      Grade
                    </span>

                    <span className="text-sm font-semibold text-slate-900">
                      {user.academic
                        ?.grade ||
                        EMPTY}
                    </span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-sm text-slate-500">
                      Section
                    </span>

                    <span className="text-sm font-semibold text-slate-900">
                      {user.academic
                        ?.section ||
                        EMPTY}
                    </span>
                  </div>
                </div>
              </Section>
            )}
          </aside>
        </div>

        {updateState.isError && (
          <div className="fixed bottom-6 right-6 z-50 max-w-md rounded-xl border border-red-200 bg-white p-4 shadow-2xl">
            <p className="text-sm font-bold text-red-700">
              Unable to update user
            </p>

            <p className="mt-1 text-xs text-red-600">
              {(updateState.error as any)
                ?.data?.message ||
                'Something went wrong while saving changes.'}
            </p>
          </div>
        )}

        {updateState.isSuccess && (
          <div className="fixed bottom-6 right-6 z-50 flex items-center gap-2 rounded-xl border border-emerald-200 bg-white px-4 py-3 shadow-2xl">
            <div className="flex h-7 w-7 items-center justify-center rounded-full bg-emerald-50">
              <Check
                size={15}
                className="text-emerald-600"
              />
            </div>

            <p className="text-sm font-semibold text-emerald-700">
              User updated successfully
            </p>
          </div>
        )}
      </div>
    </div>
  )
}
